    62    run = new_run ();
    63
    64    if LIKELY
    65      (run)
    66      {
    67        run->type = FRIBIDI_TYPE_SENTINEL;
    68        run->level = FRIBIDI_SENTINEL;
    69        run->pos = FRIBIDI_SENTINEL;
    70        run->len = FRIBIDI_SENTINEL;
    71        run->next = run->prev = run;
